"""Final report generated only from actual published observation pairs."""
import json,csv
from backend.config import DATA,ROOT
from backend.monitoring import reservoirs
from backend.active import monitoring
original=json.loads((DATA/'internal/original-sixteen-scale-snapshot.json').read_text());rows=reservoirs();pending=json.loads((DATA/'internal/pending-reservoirs.json').read_text());discovery=json.loads((DATA/'internal/scale-discovery-audit.json').read_text());processing=json.loads((ROOT/'output/scale-processing-results.json').read_text())
new=[r for r in rows if r['id'] not in original];publicids={r['id'] for r in rows};candidateids={'basava-sagara','malaprabha'}|{a['id'] for a in discovery};unpublished=candidateids-publicids
headers=['Reservoir','District or region','Polygon source','Earlier date','Latest date','Chlorophyll-a (µg/L)','Absolute change (µg/L)','Percentage change (%)','EPA category','RGB','Heatmap','Map','Verification status']
values=[]
for r in rows:
 m=monitoring(r['id']);a=m['previous'];b=m['latest'];region=r.get('district') or r.get('region') or r.get('location') or 'Karnataka (district unverified)'
 values.append([r['name'],region,r['osm_url'],a['observed_at'][:10],b['observed_at'][:10],round(m['chlorophyll_a'],5),round(m['change']['absolute'],5),round(m['change']['percent'],3),m['classification']['name'],'PASS','PASS','PASS (DOM/API)','PASS automated; visual incomplete'])
out=ROOT/'output'
with (out/'scale-reservoir-verification.csv').open('w') as f:w=csv.writer(f);w.writerow(headers);w.writerows(values)
lines=['# NEERWATCH: operational coverage scaling','','## Outcome',f'- Previous operational count: 16.',f'- Successful new additions: {len(new)}.',f'- Final operational count: {len(rows)}.',f'- Investigated candidates not published in this phase: {len(unpublished)}.',f'- Total internal pending inventory records: {len(pending)} (includes previously excluded coordinate-only/tank records; not a count of operational reservoirs).','- Original sixteen latest/history manifests and boundary file hashes preserved unchanged.','- No ordinary tanks, simulated observations, forecasting or laboratory-validation claims were added.','','## Per-reservoir verification','','Districts are not inferred from nearby towns. Where no verified district field exists, the sourced locality/region is shown. Water polygons come from the linked original OpenStreetMap geometry, checked against government dam locations and real Sentinel-2 SCL water pixels.','','|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']
for value in values:lines.append('|'+'|'.join(str(v).replace('|','/') for v in value)+'|')
lines+=['','The CSV version is output/scale-reservoir-verification.csv. Concentrations are experimental satellite-derived screening estimates, not field-measured chlorophyll. All pairs use matching method, reflectance correction, grid, masks and algorithm screening settings.','','## Multi-tile results','']
for rid in ['basava-sagara','malaprabha']:
 m=monitoring(rid);lines.append('### '+rid)
 for r in [m['previous'],m['latest']]:
  lines.append(f"- {r['observed_at']}: {r['chlorophyll_a']:.5f} µg/L; {len(r['source_scenes'])} source tiles; provider-reported timestamp difference {r['mosaic_time_difference_seconds']} seconds; footprint union {r['quality']['footprint_fraction']:.2%}; actual grid data coverage {r['quality']['data_footprint_fraction']:.2%}; {r['quality']['algorithm_valid_pixels']:,} valid concentration pixels. Composite identifier `{r['item_id']}`.")
  for t in r['source_scenes']:lines.append('  - '+t['scene_id']+' · '+t['observed_at'])
lines+=['','Tiles are grouped by date, platform, relative orbit and processing baseline, with at most 300 seconds difference in provider STAC timestamps. Each source is scaled using its own native scale/offset, reprojected to the shared 60 m UTM grid, and assigned a deterministic integer owner per grid pixel. All spectral bands use the same owner; overlap pixels are not averaged or counted twice. QC is applied after mosaicking, including unchanged 95% full-reservoir footprint and all cloud/water/shoreline/reflectance gates. No observations from different days are combined. Composite identifiers are explicitly distinguished from source scene IDs, which remain saved in source_scenes.','','## Scientific audit','','Equation: (35.75 × B05/B04 − 19.30)^1.124. Coefficients were not changed to increase coverage. [Gilerson et al.](https://doi.org/10.1364/OE.18.024109) and the existing FCMm reference expression were used for numerical agreement checks. NDCI remains dimensionless. Native DN scale/offset are retained per source band; all calculation inputs are reflectance. Output mg/m³ and µg/L are numerically equivalent. The provider Sen2Cor BOA approximation is experimental and is not ACOLITE aquatic correction. See data/internal/scale-algorithm-audit.json.','','EPA categories remain ≤2 oligotrophic, >2–7 mesotrophic, >7–30 eutrophic and >30 hypereutrophic µg/L. They describe trophic screening and are not bloom probability or toxicity alerts. Source: https://nationallakesassessment.epa.gov/webreport/#trophic-state.','','## Unpublished candidates and reasons','']
for rid in sorted(unpublished):
 d=next((x for x in discovery if x['id']==rid),{});p=next((x for x in reversed(processing) if x['id']==rid),{})
 reason=d.get('reason') or p.get('reason')
 if not reason:reason='Held outside public registry because the 46-reservoir phase target was reached; no incomplete workspace published.'
 lines.append('- '+rid+': '+reason)
 if d.get('osm_api_error'):lines.append('  - Original OSM API diagnostic: '+d['osm_api_error'].split('\n')[0])
lines+=['','Government verification: [CWC National Register of Large Dams 2019](https://www.cwc.gov.in/sites/default/files/nrld-2019.pdf). PICs, register names, physical PDF pages, official dam coordinates and distances to the original water polygons are retained in data/internal/scale-discovery-audit.json. Polygon topology, location, nonduplication against existing reservoirs and substantial mapped water area were checked before processing. Ordinary tank entries without independent reservoir qualification were excluded.','','## Tests and persistence','','- Backend tests: 60 passed (one existing Starlette/httpx deprecation warning); final expanded-inventory run is recorded in work/scale-tests-final.log.','- Frontend production build passed.','- Each new earlier/latest pair independently recomputed from saved B04/B05 arrays: concentration, median, valid counts, scene IDs, GeoTIFF pixels and EPSG:32643 checked.','- Live API audit verifies all published concentration/category/image/map/raster outputs.','- React and actual Leaflet integration tests execute the real bundle against the real API in two fresh jsdom sessions: every workspace loads cached dates/concentration/category/change, all boundary SVGs render, polygon clicks and named concentration/category popups work, and comparison sorting is checked.','- A separate staging registry/API is audited before publication. Main backend is restarted, then public API and frontend-state tests are repeated to check persisted results.','- Visual browser inspection remains INCOMPLETE because browser control is disabled. DOM state checks are not represented as visual layout or overlay verification.','','## Comparison and mapping','','Every operational reservoir polygon is rendered on the existing Leaflet map. Selection fits/highlights the real boundary and synchronizes the workspace; popups include name, latest concentration and EPA category. The restored comparison table includes name, region, both acquisition dates/concentrations, absolute/percentage change, EPA category and lazy-loaded previews and links to actual RGB and heatmap. Sorts include name, concentration, increase, decrease and category. CSV export includes the same calculated fields.','','GeoTIFF downloads are georeferenced and verified. The optional in-map coloured raster overlay was deferred; the PNG with its colourbar is not claimed to be a georeferenced map overlay.','','## Changed files','','- pipeline/mosaic.py — acquisition grouping and mosaic provenance.','- pipeline/satellite.py — common-grid tile ownership, per-tile reflectance conversion, mosaic footprint/QC.','- pipeline/sentinel2_chlorophyll.py — mosaic processing and resumable cached scenes.','- backend/config.py and backend/monitoring.py — isolated staging registry support.','- backend/readiness.py — require persisted source spectral arrays and explicit µg/L units.','- backend/main.py — comparison CSV fields and explicit scene-pinned media access.','- frontend/src/main.jsx and frontend/src/style.css — all operational polygons, enriched popups, comparison previews and sorting.','- scripts/prepare_scale_candidates.py, scale_osm_api.py, scale_overpass.py — official-record matching and original polygon retrieval.','- scripts/scale_batch1.py, run_scale_queue.py, resume_scale_queue.py — sequential resumable processing.','- scripts/stage_scale_batch.py — independent pair audit, staging and tested publication gate.','- scripts/verify_live_processing.py, frontend-check/check.mjs — live API and frontend/Leaflet checks.','- scripts/report_scale_results.py and scale_snapshot.py — reporting and original-output snapshot.','- tests/test_mosaic.py, tests/test_scale_snapshot.py, tests/test_scale_publication.py — compatible acquisition/ownership, original-sixteen preservation, 46-entry readiness and scene-pinned media checks.','- tests/test_sentinel2.py, tests/test_coverage_integrity.py — count limit updated for requested 46.','- data/reservoirs.json, data/internal/*, new data/boundaries/*.geojson and new data/sentinel2/* — audited registry, original source metadata and real processed outputs.','','## Remaining limitations','','Satellite-derived chlorophyll-a estimates have not yet been validated against Karnataka field measurements. Full water-specific atmospheric correction, local calibration, toxicity detection and forecasting are not provided. No field accuracy scores were manufactured. Browser visual alignment/layout verification remains incomplete. The running app is local at http://127.0.0.1:8010; no external production deployment was changed. Approximately 140 reservoirs remains a future architectural goal, not an asserted authoritative denominator or this phase’s publication target.']
(out/'scale-to-46-report.md').write_text('\n'.join(lines)+'\n');print('REPORT',len(rows),'public',len(new),'new',len(unpublished),'unpublished candidates')
